package com.sneha.snehamart.service;
import java.util.Locale;
/** Offline FAQ provider for the SnehaMart product and order domain. */
public final class MockChatProvider implements ChatProvider {public String getReply(String userMessage,String context){String q=userMessage.toLowerCase(Locale.ROOT);if(q.contains("ship"))return "Orders over ₹2,499 ship free. We usually prepare your little finds in 1–2 business days. ♡";if(q.contains("return"))return "If something doesn't feel quite right, contact us within 7 days of delivery and we'll help make it lovely again. ♡";if(q.contains("size"))return "Our made-for-you dresses can be tailored. Check each listing for its fit notes, then message us if you need a hand. ♡";if(q.contains("payment")||q.contains("pay"))return "Checkout here is a mock confirmation for your project demo — no real payment is taken. ♡";if(q.contains("dress"))return "Our dress edit is made for main-character moments. Browse The dress edit to find your favorite. ♡";if(q.contains("accessor"))return "Our little extras include jewelry, hair clips, and the cutest mini tech finds for your everyday. ♡";return "I'm your SnehaMart helper! Ask me about dresses, sizing, shipping, returns, accessories, or checkout. ♡";}}
